// A const member function that is NOT thread-safe due to mutable members.
class Polynomial {
public:
  using RootsType = std::vector<double>;

  RootsType roots() const {
    if (!rootsAreValid) {      // Race condition: two threads could enter here
      // ... compute roots ...
      rootVals = {1.0, 2.0}; // Race condition: concurrent writes
      rootsAreValid = true;    // Race condition: concurrent writes
    }
    return rootVals;
  }

private:
  mutable bool rootsAreValid{false};
  mutable RootsType rootVals{};

  // To make this thread-safe, you would add a mutable mutex:
  // mutable std::mutex m;
  // And then use a std::lock_guard<std::mutex> inside roots().
};
